(()=>{
const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const bands=['€50,000 to under €100,000','€100,000 to under €500,000','€500,000 to under €1 million','€1 million to €5 million','Above €5 million'];
q('#pb-assets').replaceChildren(new Option('Select…',''),...bands.map(v=>new Option(v,v)));
q('#pb-name').closest('label').querySelector('span').textContent='Name and surname';
['pb-timeline','pb-bank-country'].forEach(id=>{q('#'+id).required=false;q('#'+id).closest('label').hidden=true;});
const chf=document.createElement('label');chf.innerHTML='<input type="checkbox" value="CHF">CHF';q('#pb-currencies .checks').append(chf);
q('#pb-assets').onchange=()=>q('#pb-eligibility').hidden=true;q('#pb-eligibility').hidden=true;
// Multi-selects collapse after each selection, or on Escape/outside click.
document.addEventListener('change',e=>{if(e.target.matches('.country-options input[type=checkbox]')){const d=e.target.closest('details');d.open=false;d.querySelector('summary').focus();}});
document.addEventListener('click',e=>all('.country-picker details[open]').forEach(d=>{if(!d.contains(e.target))d.open=false;}));
document.addEventListener('keydown',e=>{if(e.key==='Escape')all('.country-picker details[open]').forEach(d=>{d.open=false;d.querySelector('summary').focus();});});
const style=document.createElement('style');style.textContent='.country-picker .selected-countries{display:none}.country-picker details{position:relative}.country-picker details[open]{background:#fff;box-shadow:0 6px 16px #0001}.country-picker summary{overflow-wrap:anywhere}';document.head.append(style);
// Keep useful prompting and reject clearly insufficient descriptions, without claiming semantic verification.
const descriptions=['activity','pb-career','pb-wealth-story','pb-funds-story','finance-use','finance-borrowing','finance-security-details'];
descriptions.forEach(id=>{const e=q('#'+id);if(!e)return;e.minLength=0;const hint=document.createElement('span');hint.className='hint';hint.textContent='What do you provide, and who are your customers? Relevant details help us tailor the options.';e.after(hint);e.addEventListener('input',()=>e.setCustomValidity(''));});
const entity=document.createElement('label');entity.className='field';entity.innerHTML='<span>Legal entity type</span><select id="entity-type" required><option value="">Select…</option><option>Private limited company (Ltd / LLC or equivalent)</option><option>Public limited company (PLC or equivalent)</option><option>Partnership</option><option>Limited liability partnership (LLP)</option><option>Association</option><option>Foundation</option><option>Other legal entity</option></select><input id="entity-type-other" hidden placeholder="Please specify the legal form">';q('[data-screen="1"] .panel:nth-of-type(2)').append(entity);
q('#entity-type').onchange=()=>{const other=q('#entity-type').value==='Other legal entity';q('#entity-type-other').hidden=!other;q('#entity-type-other').required=other;};
const rep=document.createElement('section');rep.className='panel';rep.innerHTML='<h2>Your relationship to the company</h2><label class="field"><span>In what capacity are you applying?</span><select id="representative-role" required><option value="">Select…</option><option>Director / officer</option><option>Employee</option><option>Shareholder / beneficial owner</option><option>External lawyer</option><option>External accountant</option><option>External corporate-services provider</option><option>Other authorised representative</option></select></label><label class="field" id="representative-firm-field" hidden><span>Firm name and your role</span><input id="representative-firm"></label><label class="checkline"><input id="representative-authority" type="checkbox"><span>I am authorised to submit this request and provide information on behalf of this legal entity.</span></label><p class="hint">SOPHIMA may request evidence of your authority before progressing an introduction.</p>';q('[data-screen="5"]').insertBefore(rep,q('[data-screen="5"] .actions'));
q('#representative-role').onchange=()=>{const ext=/External|Other/.test(q('#representative-role').value);q('#representative-firm-field').hidden=!ext;q('#representative-firm').required=ext;};
const structure=document.createElement('section');structure.className='panel';structure.hidden=true;structure.innerHTML='<h2>Control and governance</h2><label class="field"><span>Who controls or governs this entity?</span><textarea id="nonshare-structure" placeholder="Describe the governing body and controlling persons, their roles, nationalities and countries of residence."></textarea></label><p class="hint">An association or foundation may not have shareholders. SOPHIMA will clarify the relevant controlling persons and beneficiaries.</p>';q('[data-screen="4"]').append(structure);
const standardPanels=[...q('[data-screen="4"]').querySelectorAll('section')].filter(s=>s!==structure);
function entityStructure(){const nonshare=['Association','Foundation'].includes(q('#entity-type').value);structure.hidden=!nonshare;standardPanels.forEach(s=>s.hidden=nonshare);}
q('#entity-type').addEventListener('change',entityStructure);
const previousOwnership=ownershipReady;ownershipReady=function(){if(['Association','Foundation'].includes(q('#entity-type').value)){if(q('#nonshare-structure').value.trim().length<30){note('Please describe the entity’s governing body and controlling persons in the Ownership step.');return false;}return true;}return previousOwnership();};

const priorRefresh=refreshFlow;refreshFlow=function(){priorRefresh();const edit=q('[data-screen="6"] [data-page]');edit.textContent='Edit my assessment';edit.onclick=()=>showPage(q('#applicant').value==='individual'?20:1);};window.refreshFlow=refreshFlow;
const oldSubmit=q('#submit').onclick;q('#submit').onclick=()=>{if(!q('#representative-role').value||!q('#representative-authority').checked||(q('#representative-firm').required&&!q('#representative-firm').value.trim())){note('Please select your relationship to the company, provide your firm details where relevant, and confirm you are authorised to act.');return;}oldSubmit();};
const oldReview=review;review=function(){oldReview();for(const [title,id] of [['Legal entity type','entity-type'],['Representative capacity','representative-role']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=title;dd.textContent=q('#'+id).value||'Not yet provided';q('#review-summary').append(dt,dd);}};
// Migrate the old positional draft around the newly added CHF control.
try{const key='finsyndeo-whole-review-unified-draft-v1';const d=JSON.parse(localStorage.getItem(key)||'null');if(d&&!d.version){const st=d.screens.find(s=>s.id==='21');if(st)st.values.splice(14,0,{value:'CHF',checked:false});d.version=2;localStorage.setItem(key,JSON.stringify(d));}}catch(e){}
refreshFlow();
})();
